import os
import sys
import shutil

def delete_files(directory, number_of_files):
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath):
            os.remove(filepath)
        else:
            shutil.rmtree(filepath)
    return len(os.listdir(directory))
